// These flags span the complete user operation, including response parsing and
// follow-up requests. A fetch alone ends when its response headers arrive.
for (const key of ["savingSchema", "savingRecord", "loadingRecord", "backingUp", "attachmentImportBusy", "savingGeneralDefinitions"]) {
  let current = Boolean(state[key]);
  Object.defineProperty(state, key, {
    enumerable: true,
    configurable: true,
    get: () => current,
    set(value) {
      const changed = current !== Boolean(value);
      current = Boolean(value);
      if (changed && typeof queueCloseReadinessCheck === "function") queueCloseReadinessCheck();
    },
  });
}

function closeRequestOperation(path, method, body) {
  if (method === "GET" || method === "HEAD") return "";
  const quietPaths = new Set([
    "/api/heartbeat", "/api/disconnect", "/api/shutdown", "/api/client-log",
    "/api/search", "/api/search/query", "/api/search/history",
    "/api/schema-finance/preview", "/api/identities/inspect", "/api/profiles/inspect",
    "/api/profile-links/matches", "/api/profile-links/options", "/api/profile-links/incoming", "/api/profile-links/select",
    "/api/field-rules/validate-row", "/api/field-rules/convert",
    "/api/import/inspect", "/api/import/preview", "/api/import/portable/inspect", "/api/import/history/log",
  ]);
  if (method === "POST" && quietPaths.has(path)) return "";
  if (path === "/api/reports") {
    let action = "";
    try { action = JSON.parse(typeof body === "string" ? body : "{}").action || ""; } catch {}
    if (["catalog", "list", "profiles", "validate", "document_validate", "draft_list", "draft_read", "recipe_list", "recipe_read", "writer_list", "writer_read", "writer_validate", "writer_status", "writer_inspect", "writer_preflight", "writer_download"].includes(action)) return "";
    return scText("عملية التصدير أو إنشاء التقرير ما زالت قيد التنفيذ.");
  }
  if (path.startsWith("/api/import/attachments/")) return scText("استيراد المرفقات ما زال قيد التنفيذ.");
  if (path.startsWith("/api/import/")) return scText("عملية الاستيراد ما زالت قيد التنفيذ.");
  if (path === "/api/export/destination") return scText("اختيار مكان التصدير ما زال قيد التنفيذ.");
  if (path.startsWith("/api/export/")) return scText("عملية التصدير أو إنشاء التقرير ما زالت قيد التنفيذ.");
  if (/attachment|upload/.test(path)) return scText("نقل أو حفظ المرفقات ما زال قيد التنفيذ.");
  if (path.startsWith("/api/records")) return method === "DELETE"
    ? scText("حذف السجل ما زال قيد التنفيذ.")
    : scText("حفظ السجل الحالي ما زال قيد التنفيذ.");
  if (path === "/api/archive") return scText("تحديث أرشفة السجل ما زال قيد التنفيذ.");
  if (path === "/api/backup") return scText("إنشاء النسخة الاحتياطية ما زال قيد التنفيذ.");
  if (path.startsWith("/api/storage/")) return scText("فحص البيانات أو ترحيلها إلى PostgreSQL ما زال قيد التنفيذ.");
  if (path === "/api/global-definitions") return scText("حفظ التعريفات العامة ما زال قيد التنفيذ.");
  if (path.startsWith("/api/schema")) return scText("حفظ التصميم أو تحديث المصنف ما زال قيد التنفيذ.");
  if (path === "/api/workspace/select") return scText("تبديل التصميم ما زال قيد التنفيذ.");
  if (path.startsWith("/api/workspace/")) return scText("تحديث تصاميم مساحة العمل ما زال قيد التنفيذ.");
  if (path.startsWith("/api/history/") || path.startsWith("/api/entry/history")) return scText("حفظ سجل العملية ما زال قيد التنفيذ.");
  if (/settings|ui-text|language|users/.test(path)) return scText("حفظ الإعدادات ما زال قيد التنفيذ.");
  if (path.startsWith("/api/session/") || path.startsWith("/api/builder/")) return scText("تحديث جلسة المستخدم ما زال قيد التنفيذ.");
  return scText("تحديث بيانات التطبيق ما زال قيد التنفيذ.");
}

const nativeFetch = window.fetch.bind(window);
window.fetch = async (input, init = {}) => {
  const candidate =
    typeof input === "string" || input instanceof URL ? input : input.url;
  const url = new URL(candidate, window.location.href);
  if (window.SchemaCraftUITextEditor?.active && url.origin === window.location.origin &&
      url.pathname.startsWith('/api/') && !['GET', 'HEAD'].includes((init.method || input?.method || 'GET').toUpperCase()) &&
      !['/api/ui-text', '/api/heartbeat', '/api/disconnect', '/api/client-log'].includes(url.pathname)) {
    throw new Error(scText('وظائف التطبيق متوقفة أثناء تعديل نصوص الواجهة. احفظ أو تجاهل التغييرات أولًا.'));
  }

  const trackRequest =
    url.origin === window.location.origin &&
    url.pathname.startsWith("/api/") &&
    !["/api/heartbeat", "/api/disconnect", "/api/shutdown"].includes(url.pathname);
  if (
    url.origin === window.location.origin &&
    url.pathname.startsWith("/api/") &&
    state.activeSchemaId &&
    !url.pathname.startsWith("/api/workspace")
  ) {
    const headers = new Headers(init.headers || {});
    if (!headers.has("X-Schema-ID") && !url.searchParams.has("schema_id")) {
      headers.set("X-Schema-ID", state.activeSchemaId);
    }
    init = { ...init, headers };
  }
  if (url.origin === window.location.origin && url.pathname.startsWith('/api/')) {
    const headers = new Headers(init.headers || {});
    headers.set('X-SchemaCraft-Language', window.SchemaCraftI18n?.language || 'ar');
    init = { ...init, headers };
  }
  const method = String(init.method || (typeof input !== 'string' && input?.method) || 'GET').toUpperCase();
  const operation = closeRequestOperation(url.pathname, method, init.body);
  const blocksClose = trackRequest && method !== 'GET' && method !== 'HEAD' && Boolean(operation);
  if (trackRequest) state.activeRequests += 1;
  if (blocksClose) {
    state.closeBlockingRequests += 1;
    state.closeBlockingPaths.set(url.pathname,(state.closeBlockingPaths.get(url.pathname)||0)+1);
    state.closeBlockingOperations.set(operation,(state.closeBlockingOperations.get(operation)||0)+1);
    if (typeof queueCloseReadinessCheck === "function") queueCloseReadinessCheck();
  }
  try {
    return await nativeFetch(input, init);
  } finally {
    if (trackRequest) state.activeRequests = Math.max(0, state.activeRequests - 1);
    if (blocksClose) {
      state.closeBlockingRequests = Math.max(0,state.closeBlockingRequests-1);
      const left=(state.closeBlockingPaths.get(url.pathname)||1)-1;
      if(left>0)state.closeBlockingPaths.set(url.pathname,left);else state.closeBlockingPaths.delete(url.pathname);
      const remaining = (state.closeBlockingOperations.get(operation) || 1) - 1;
      if (remaining > 0) state.closeBlockingOperations.set(operation, remaining);
      else state.closeBlockingOperations.delete(operation);
      if (typeof queueCloseReadinessCheck === "function") queueCloseReadinessCheck();
    }
  }
};

