      const px=Math.ceil(action?Math.max(96,Math.min(176,content+16)):Math.min(340,Math.max(96,headerWidth+headerExtra,content+inset(cell)+8)));
      const col=el('col');col.style.width=px+'px';group.append(col);total+=px;
